<?php declare(strict_types=1);use NpmGateway\Services\RmCorrectionStatus;use NpmGateway\Support\GatewayDateTimeFormatter;$e=static fn(mixed$v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$components=dirname(__DIR__,2).'/components';$labels=RmCorrectionStatus::LABELS;$badges=RmCorrectionStatus::BADGES;ob_start();$heading='RM Corrections';$description='Review and process Rent Manager correction requests from all communities.';$eyebrow='Corporate';$actionsHtml='';require$components.'/page-header.php';?><div class="gateway-review-summary d-flex flex-wrap gap-2" role="status" aria-label="RM Corrections status summary"><?php foreach($labels as$s=>$l):$statusLabel=$counts[$s].' '.$l;$statusType=$badges[$s];require$components.'/status-badge.php';endforeach;?></div><form class="gateway-filter-bar" method="get"><label>Search<input class="form-control" type="search" name="search" value="<?=$e($search)?>"></label><label>Status<select class="form-select" name="status"><option value="">All statuses</option><?php foreach($labels as$v=>$l):?><option value="<?=$v?>"<?=$status===$v?' selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Property<select class="form-select" name="property"><option value="">All Properties</option><?php foreach($properties as$p):?><option value="<?=$e($p['public_id'])?>"<?=$propertyPublicId===$p['public_id']?' selected':''?>><?=$e($p['display_name'])?></option><?php endforeach;?></select></label><button class="btn btn-secondary">Apply Filters</button></form><?php if(!$requests):$emptyTitle=$search!==''||$status!==''||$propertyPublicId!==''?'No RM correction requests match these filters.':'No RM correction requests are waiting for review.';$emptyMessage=$emptyIconHtml=$emptyActionHtml='';require$components.'/empty-state.php';else:?><div class="table-responsive"><table class="table gateway-directory-table"><thead><tr><th>Property</th><th>Lot / Address</th><th>Tenant</th><th>Submitted By</th><th>Submitted</th><th>Status</th><th>Last Updated</th><th>Action</th></tr></thead><tbody><?php foreach($requests as$r):?><tr><td><?=$e($r['property_name'])?></td><td><?=$e($r['lot_address'])?></td><td><?=$e($r['tenant_name'])?></td><td><?=$e($r['submitted_by_name'])?></td><td><?=$e(GatewayDateTimeFormatter::format($r['submitted_at']))?></td><td><?php $statusLabel=$labels[$r['status']];$statusType=$badges[$r['status']];require$components.'/status-badge.php';?></td><td><?=$e(GatewayDateTimeFormatter::format($r['updated_at']))?></td><td><a href="/corporate/rm-corrections/<?=$e($r['public_id'])?>"><?=$r['status']==='pending_review'?'Review':'View'?></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;$contentHtml=(string)ob_get_clean();$pageTitle='RM Corrections — NPM Gateway';$navbarItems=\NpmGateway\Support\Navigation::forRoute('/corporate/rm-corrections',dirname(__DIR__,4));$navbarUserLabel=$user->displayName;$navbarUserContext='@'.$user->username;require dirname(__DIR__,2).'/layouts/app.php';
